package com.mauricioliveira.awesomenotes.core.domain.repository

import com.mauricioliveira.awesomenotes.core.domain.model.Note
import kotlinx.coroutines.flow.Flow

interface NoteRepository {

    /** The cached notes, most recently updated first, and every later change. */
    fun observeNotes(): Flow<List<Note>>

    /** The cached note, or null if it is not cached. */
    fun observeNote(id: String): Flow<Note?>

    /** Downloads the user's notes and replaces the cache. */
    suspend fun refresh(): Result<Unit>

    /**
     * [id] is generated by the caller and kept across retries,
     * so a retry after a lost response does not create a duplicate.
     */
    suspend fun create(id: String, title: String, content: String): Result<Note>

    suspend fun update(id: String, title: String, content: String): Result<Note>

    suspend fun delete(id: String): Result<Unit>
}
